import React, { useEffect, useRef, useState } from "react";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);
  const animationRef = useRef();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  const onMouseDown = (e) => {
    isDragging.current = true;
    position.current = { x: e.clientX, y: e.clientY };
  };

  const onMouseMove = (e) => {
    if (!isDragging.current) return;
    const dx = e.clientX - position.current.x;
    const dy = e.clientY - position.current.y;
    offset.current.x += dx;
    offset.current.y += dy;
    position.current = { x: e.clientX, y: e.clientY };
    containerRef.current.style.transform = `translate(${offset.current.x}px, ${offset.current.y}px)`;
  };

  const onMouseUp = () => {
    isDragging.current = false;
  };

  const onTouchStart = (e) => {
    isDragging.current = true;
    position.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
  };

  const onTouchMove = (e) => {
    if (!isDragging.current) return;
    const dx = e.touches[0].clientX - position.current.x;
    const dy = e.touches[0].clientY - position.current.y;
    offset.current.x += dx;
    offset.current.y += dy;
    position.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    containerRef.current.style.transform = `translate(${offset.current.x}px, ${offset.current.y}px)`;
  };

  const onTouchEnd = () => {
    isDragging.current = false;
  };

  const generateGrain = (ctx, width, height, intensity = 200, gamma = 1.2) => {
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;

    for (let i = 0; i < data.length; i += 4) {
      // Add grain
      const noise = Math.floor(Math.random() * intensity) - intensity / 2;
      data[i] = Math.min(255, Math.max(0, data[i] + noise));     // Red
      data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + noise)); // Green
      data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + noise)); // Blue

      // Apply gamma correction
      data[i] = 255 * Math.pow(data[i] / 255, 1 / gamma);
      data[i + 1] = 255 * Math.pow(data[i + 1] / 255, 1 / gamma);
      data[i + 2] = 255 * Math.pow(data[i + 2] / 255, 1 / gamma);
    }

    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height, gap = 4, alpha = 0.1) => {
    ctx.save();
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    for (let y = 0; y < height; y += gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };


  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const TILE_SIZE = 36;
    const GRID = 30;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    const getShuffledIndices = () => {
      const indices = Array.from({ length: GRID * GRID }, (_, i) => i);
      for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
      }
      return indices;
    };

    const sliceAndShuffle = (img) => {
      const tempCanvas = document.createElement("canvas");
      tempCanvas.width = 1080;
      tempCanvas.height = 1080;
      const tempCtx = tempCanvas.getContext("2d");
      tempCtx.drawImage(img, 0, 0, 1080, 1080);

      const tiles = [];
      for (let y = 0; y < GRID; y++) {
        for (let x = 0; x < GRID; x++) {
          tiles.push(tempCtx.getImageData(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE));
        }
      }

      const shuffledIndices = getShuffledIndices();
      const shuffledCanvas = document.createElement("canvas");
      shuffledCanvas.width = 1080;
      shuffledCanvas.height = 1080;
      const shuffledCtx = shuffledCanvas.getContext("2d");

      shuffledIndices.forEach((toIdx, fromIdx) => {
        const x = (toIdx % GRID) * TILE_SIZE;
        const y = Math.floor(toIdx / GRID) * TILE_SIZE;
        shuffledCtx.putImageData(tiles[fromIdx], x, y);
      });

      return shuffledCanvas;
    };

    const thresholdImage = (canvas) => {
      const ctx = canvas.getContext("2d");
      const imageData = ctx.getImageData(0, 0, 1080, 1080);
      const data = imageData.data;

      for (let i = 0; i < data.length; i += 4) {
        const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
        const val = avg > 128 ? 255 : 0;
        data[i] = data[i + 1] = data[i + 2] = val;
      }

      ctx.putImageData(imageData, 0, 0);
      return canvas;
    };

    const applyPixelate = (canvas, blockSize = 10) => {
      const ctx = canvas.getContext("2d");
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      for (let y = 0; y < canvas.height; y += blockSize) {
        for (let x = 0; x < canvas.width; x += blockSize) {
          const i = (y * canvas.width + x) * 4;
          const r = data[i];
          const g = data[i + 1];
          const b = data[i + 2];

          for (let dy = 0; dy < blockSize; dy++) {
            for (let dx = 0; dx < blockSize; dx++) {
              const ii = ((y + dy) * canvas.width + (x + dx)) * 4;
              data[ii] = r;
              data[ii + 1] = g;
              data[ii + 2] = b;
            }
          }
        }
      }

      ctx.putImageData(imageData, 0, 0);
      return canvas;
    };

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      const shuffledOddCanvas = document.createElement("canvas");
      shuffledOddCanvas.width = 1080;
      shuffledOddCanvas.height = 1080;
      const shuffledOddCtx = shuffledOddCanvas.getContext("2d");

      [0, 2, 4].forEach((i) => {
        if (images[i]) {
          const shuffled = sliceAndShuffle(images[i]);
          shuffledOddCtx.drawImage(shuffled, 0, 0);
        }
      });

      applyPixelate(shuffledOddCanvas);
      ctx.drawImage(shuffledOddCanvas, 0, 0);

      [1, 3].forEach((i) => {
        if (images[i]) {
          const shuffled = sliceAndShuffle(images[i]);
          const pixelated = applyPixelate(shuffled);
          const bwCanvas = thresholdImage(pixelated);
          const bwCtx = bwCanvas.getContext("2d");
          const bwData = bwCtx.getImageData(0, 0, 1080, 1080).data;
          const baseData = ctx.getImageData(0, 0, 1080, 1080);

          for (let j = 0; j < baseData.data.length; j += 4) {
            const alpha = bwData[j] / 255;
            baseData.data[j + 3] *= alpha;
          }
          ctx.putImageData(baseData, 0, 0);
        }
      });

      generateGrain(ctx, canvas.width, canvas.height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300); // fade-out duration
  };

  return (
    <div
      ref={containerRef}
      onMouseDown={onMouseDown}
      onMouseMove={onMouseMove}
      onMouseUp={onMouseUp}
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
      style={{
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        position: "relative",
        touchAction: "none",
        cursor: isDragging.current ? "grabbing" : "grab",
        background: "#000",
      }}
    >
      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        style={{
          display: "block",
          margin: "0 auto",
          opacity: isFading ? 0.2 : 1,
          transition: "opacity 0.3s ease",
        }}
      />
      <button
        onClick={handleRegenerate}
        style={{
          position: "absolute",
          top: 20,
          left: 20,
          padding: "10px 20px",
          background: "#FFD666",
          border: "none",
          borderRadius: "8px",
          fontWeight: "bold",
          cursor: "pointer",
          zIndex: 10,
        }}
      >
        Regenerate
      </button>
    </div>
  );
}

export default Generate;
